SELECT route_code, origin_hub_id, destination_hub_id, distance_km, scheduled_duration_min
FROM aero_horizon_routes
WHERE is_seasonal = 1;

SELECT a.room_id, a.room_number, a.floor_level, a.has_balcony, a.status
FROM accommodations a
WHERE a.status = 'Occupied';

SELECT facility_name, city, state 
FROM medical_facilities 
WHERE is_active = 1;

SELECT product_name, product_id
FROM product_lines
WHERE is_legacy = 1;

SELECT AVG(monthly_mrr) AS avg_monthly_mrr, subscription_tier
FROM customer_accounts
GROUP BY subscription_tier;

SELECT f.full_name, f.specialization, f.hourly_rate
FROM facilitator f
WHERE f.is_active = 0;

SELECT gp.title, sm.full_name
FROM game_project gp
JOIN studio_member sm ON sm.lead_producer_id = gp.project_id;

SELECT city, COUNT(*) AS total_viewings, COUNT(DISTINCT buyer_id) AS unique_buyers
FROM viewings
GROUP BY city;

SELECT block_id, block_name, acreage, primary_variety, planting_year, irrigation_type 
FROM orchard_blocks 
WHERE acreage > 20;

SELECT destination_market, COUNT(*) AS shipment_count, SUM(revenue_usd) AS total_revenue
FROM market_shipments
GROUP BY destination_market;

SELECT e.title, e.start_datetime 
FROM event e 
WHERE e.status = 'On Sale';

SELECT f.tail_number, a.airline_name, a.hub_airport_code
FROM fleet f
JOIN airlines a ON f.airline_id = a.airline_id;

SELECT mc.generic_name, mc.brand_name, mc.strength, mc.controlled_substance_schedule
FROM medication_catalog mc
WHERE mc.controlled_substance_schedule >= 2;

SELECT a.subscription_id, a.account_id, a.plan_id, a.current_period_start, a.current_period_end, a.status
FROM active_subscriptions a
WHERE a.status = 'Past_Due';

SELECT DISTINCT account_id, company_name, billing_country
FROM customer_accounts
WHERE billing_country = 'United States';

SELECT outlet_id, COUNT(*) AS member_count
FROM team_members
GROUP BY outlet_id;

SELECT outlet_id, AVG(rating) AS avg_rating
FROM guest_feedback
GROUP BY outlet_id;

SELECT outlet_id, MAX(last_restock_date) AS most_recent_restock_date
FROM inventory_stock
GROUP BY outlet_id;

SELECT c.full_name, s.tier_name, s.monthly_fee
FROM customer_accounts c
JOIN subscription_tiers s ON c.tier_id = s.tier_id;

SELECT session_type, SUM(volume_mb) AS total_volume_mb
FROM usage_events
GROUP BY session_type;

SELECT AVG(registration_fee) AS avg_fee
FROM divisions
GROUP BY age_group;

SELECT hub_id, COUNT(*) AS crew_count
FROM crew_members
GROUP BY hub_id;
